{
  "name": "django-process-debugger",
  "displayName": "Django Process Debugger",
  "description": "Attach debugpy to a running Django/Celery process for runtime debugging without modifying your codebase",
  "version": "0.2.8",
  "publisher": "newdlops",
  "license": "MIT",
  "icon": "icon.png",
  "galleryBanner": {
    "color": "#0C4B33",
    "theme": "dark"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/newdlops/django_process_debugger"
  },
  "engines": {
    "vscode": "^1.85.0"
  },
  "categories": [
    "Debuggers"
  ],
  "keywords": [
    "django",
    "python",
    "debugger",
    "debugpy",
    "attach",
    "celery",
    "macos",
    "apple-silicon"
  ],
  "activationEvents": [],
  "main": "./out/extension.js",
  "contributes": {
    "debuggers": [
      {
        "type": "django-process",
        "label": "Django Process Debugger",
        "configurationAttributes": {
          "attach": {
            "properties": {
              "host": {
                "type": "string",
                "default": "127.0.0.1",
                "description": "Host address of the debugpy server"
              },
              "port": {
                "type": "number",
                "default": 5678,
                "description": "Port of the debugpy server"
              },
              "justMyCode": {
                "type": "boolean",
                "default": true,
                "description": "Only debug user-written code"
              }
            }
          }
        },
        "configurationSnippets": [
          {
            "label": "Django Process Debugger: Attach",
            "description": "Attach to a running Django/Celery process",
            "body": {
              "type": "django-process",
              "request": "attach",
              "name": "Attach to Django Process",
              "host": "127.0.0.1",
              "port": 5678,
              "justMyCode": true
            }
          }
        ]
      }
    ],
    "configuration": {
      "title": "Django Process Debugger",
      "properties": {
        "djangoProcessDebugger.justMyCode": {
          "type": "boolean",
          "default": true,
          "description": "When true, the debugger only steps through your code. When false, it also steps into library/framework code (e.g., Django, Celery internals)."
        },
        "djangoProcessDebugger.redirectOutput": {
          "type": "boolean",
          "default": true,
          "description": "Redirect stdout/stderr to the VS Code Debug Console. When true, print() output appears in the Debug Console instead of only in the terminal."
        },
        "djangoProcessDebugger.hotReload": {
          "type": "boolean",
          "default": true,
          "description": "When true, changed Python files are hot-reloaded via importlib.reload() without restarting the Django process, keeping the debug session alive. Django's autoreloader is suppressed while active."
        }
      }
    },
    "commands": [
      {
        "command": "djangoProcessDebugger.setup",
        "title": "Django Debugger: Setup"
      },
      {
        "command": "djangoProcessDebugger.showSetupStatus",
        "title": "Django Debugger: Show Setup Status"
      },
      {
        "command": "djangoProcessDebugger.attachToProcess",
        "title": "Django Debugger: Attach to Django Process"
      },
      {
        "command": "djangoProcessDebugger.killProcess",
        "title": "Django Debugger: Kill Django/Celery Process"
      },
      {
        "command": "djangoProcessDebugger.reinstallDebugpy",
        "title": "Django Debugger: Reinstall debugpy"
      },
      {
        "command": "djangoProcessDebugger.cleanPythonLanguageServer",
        "title": "Django Debugger: Clean All (Remove Bootstrap & Restore Python)"
      }
    ]
  },
  "scripts": {
    "vscode:prepublish": "npm run compile",
    "compile": "tsc -p ./",
    "watch": "tsc -watch -p ./",
    "lint": "eslint src --ext ts",
    "pretest": "npm run compile",
    "test": "node ./out/test/runTest.js"
  },
  "devDependencies": {
    "@types/glob": "^8.1.0",
    "@types/mocha": "^10.0.10",
    "@types/node": "^20.11.0",
    "@types/vscode": "^1.85.0",
    "@typescript-eslint/eslint-plugin": "^6.0.0",
    "@typescript-eslint/parser": "^6.0.0",
    "@vscode/test-electron": "^2.5.2",
    "eslint": "^8.0.0",
    "glob": "^10.5.0",
    "mocha": "^10.8.2",
    "typescript": "^5.3.0"
  }
}
